style.css:
@-moz-document domain("youtube.com") {
/* BACKGROUND PHOTO ONLY */
html,
body,
ytd-app {
    background-image:
    url("https://i.pinimg.com/1200x/4e/ea/55/4eea55f530badfb5a942eb1984a4ea6e.jpg") !important;

    background-size:cover !important;
    background-position:center !important;
    background-attachment:fixed !important;
    background-repeat:no-repeat !important;
}


/* REMOVE YOUTUBE DEFAULT BACKGROUND */
#page-manager,
#content,
ytd-browse,
ytd-watch-flexy {
    background:transparent !important;
}


/* YOUTUBE UI PANELS */
#masthead {

    background:
    linear-gradient(
        90deg,
        rgba(255,220,235,.90),
        rgba(215,240,255,.90)
    ) !important;

    backdrop-filter:blur(15px);
}


#guide-content,
tp-yt-app-drawer {

    background:
    linear-gradient(
        180deg,
        #ffe2ef,
        #dff5ff
    ) !important;
}


/* VIDEO CARDS */
ytd-rich-item-renderer,
ytd-video-renderer,
ytd-grid-video-renderer {

    background:
    linear-gradient(
        135deg,
        rgba(255,225,240,.85),
        rgba(220,245,255,.85)
    ) !important;

    border-radius:18px!important;

    backdrop-filter:blur(8px);

    box-shadow:
    0 5px 20px rgba(255,160,200,.25);
}


/* DARKER PINK TEXT */
#video-title,
yt-formatted-string,
a,
#channel-name,
#owner-name {

    color:#c85b8c !important;
}


/* SEARCH BAR */
#search {

    background:#fff8fc !important;

    border:2px solid #f5b7d2 !important;

    border-radius:30px !important;
}


/* BUTTONS */
button {

    color:#c85b8c !important;

    border-radius:30px!important;
}


/* GLOWING COLOR CHANGING PROGRESS BAR */

.ytp-play-progress {

    background:
    linear-gradient(
        90deg,
        #ff9fc8,
        #ffd1e5,
        #9edfff,
        #65cfff,
        #ff9fc8
    ) !important;

    background-size:300% 100% !important;

    animation:
    pinkBlueGlow 3s infinite linear;


    box-shadow:
    0 0 8px #ff9fc8,
    0 0 18px #9edfff,
    0 0 30px #ff9fc8 !important;
}


/* Progress circle */

.ytp-scrubber-button {

    background:white!important;

    border:3px solid #ff9fc8!important;

    box-shadow:
    0 0 12px #ff9fc8,
    0 0 20px #9edfff!important;
}


@keyframes pinkBlueGlow {

    0% {
        background-position:0% 50%;
    }

    50% {
        background-position:100% 50%;
    }

    100% {
        background-position:0% 50%;
    }
}


/* Scroll bar */

::-webkit-scrollbar {

    width:10px;
}


::-webkit-scrollbar-thumb {

    background:
    linear-gradient(
        #ffb6d6,
        #a9e4ff
    );

    border-radius:20px;
}
}
